  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B052",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and enable exceptionally sensitive tests and measurements.",
        "attribution": "Katori's magic-wavelength lattice-clock concept and Ye's decisive experimental development form a clear, complementary attribution.",
        "maturity": "Independent clock realizations, steadily improved performance, and broad metrological uptake make this a fully mature achievement.",
        "uncertainties": [
          "The eventual scope of applications beyond metrology remains open, although the fundamental experimental advance is unambiguous."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Christian J. Bordé",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry established a powerful family of quantum measurements with major consequences for inertial sensing and fundamental tests.",
        "attribution": "Bordé supplied foundational interferometric concepts and Kasevich made landmark precision implementations; the wider field complicates any three-person limit.",
        "maturity": "The methods have been reproduced extensively and have become precision instruments rather than isolated demonstrations.",
        "uncertainties": [
          "Credit allocation among foundational atom-interferometry contributors is necessarily incomplete in a limited laureate set."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made coherent light-matter physics available in engineered superconducting circuits and opened a major experimental quantum platform.",
        "attribution": "Blais provided central theoretical framing, while Wallraff and Schoelkopf delivered defining experimental demonstrations; Girvin's contribution is also substantial.",
        "maturity": "The platform is deeply replicated and has enabled precision quantum control, measurement, and scalable-device research.",
        "uncertainties": [
          "It remains difficult to separate the foundational circuit-QED advance cleanly from the broader superconducting-qubit enterprise."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Andrew N. Cleland",
        "Markus Aspelmeyer",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Cavity optomechanics brought macroscopic motion into the quantum-control regime and created versatile new measurement technology.",
        "attribution": "Cleland, Aspelmeyer, and Kippenberg represent complementary experimental and conceptual advances, though the community has many important contributors.",
        "maturity": "Quantum-limited measurement and control have been demonstrated across several mechanical implementations.",
        "uncertainties": [
          "The extent to which macroscopic quantum control has produced a single defining discovery rather than a broad platform is debatable."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B042",
      "proposed_laureates": [
        "Fedor Jelezko",
        "Jörg Wrachtrup",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Optical readout and coherent control of NV spins created an exceptionally useful solid-state quantum sensor and spin-photon platform.",
        "attribution": "Jelezko and Wrachtrup were central to single-defect coherent-control experiments, with Lukin important for quantum-sensing and quantum-network development.",
        "maturity": "The techniques are widely reproduced and underpin sensing experiments from nanoscale magnetometry to quantum-device research.",
        "uncertainties": [
          "The proposed grouping spans several related advances, and attribution across early optical-detection work requires careful historical review."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Alfred Y. Cho",
        "Federico Capasso",
        "Jérôme Faist"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum cascade laser was a genuinely new semiconductor-laser principle with wide practical and scientific impact in the infrared.",
        "attribution": "Faist and Capasso are directly associated with the invention and realization, while Cho's heterostructure technology was enabling and foundational.",
        "maturity": "The technology is robust, broadly deployed, and has opened important spectroscopic and sensing capabilities.",
        "uncertainties": [
          "The appropriate balance between the device invention and its prerequisite epitaxial-heterostructure work needs close attribution review."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band-gap concepts changed how physicists design and control electromagnetic modes in structured materials.",
        "attribution": "John and Yablonovitch supplied seminal independent ideas and demonstrations, while Joannopoulos was central to the theoretical and computational foundations.",
        "maturity": "Photonic-crystal physics is experimentally established and continues to influence integrated optics, emitters, and wave control.",
        "uncertainties": [
          "The achievement covers a broad field whose applications have developed unevenly across spectral ranges and platforms."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction supplied the essential physical and information-theoretic route from fragile qubits to fault-tolerant computation.",
        "attribution": "Shor, Steane, and Kitaev made distinct foundational contributions to codes, fault tolerance, and topological protection.",
        "maturity": "Core principles have been repeatedly demonstrated, but full-scale fault-tolerant computation is still developing.",
        "uncertainties": [
          "The practical threshold for broadly useful fault-tolerant machines has not yet been reached.",
          "The field has an unusually extensive set of foundational contributors beyond three names."
        ]
      }
    }
  ]
}
